"""Immutable wheel/installed payload cache; no shared writable test runtime."""

import json
from pathlib import Path
import shutil
import sys
import tempfile
from typing import Any
from framework_checks.cache import cache_lock, digest, file_digest, tree_files
from framework_checks.environment import environment_identity
from worker_install_commands import checked_command


def inputs(project: Path) -> dict[str, object]:
    sources = tree_files(project / "src")
    # Build metadata is regenerated by setuptools and is not a source input.
    sources = {
        p: v
        for p, v in sources.items()
        if not any(part.endswith(".egg-info") for part in Path(p).parts)
    }
    return {
        "sources": sources,
        "pyproject": file_digest(project / "pyproject.toml"),
        "readme": file_digest(project / "README.md"),
        "recipe": {
            name: file_digest(Path(__file__).with_name(name))
            for name in (
                "worker_install_cache.py",
                "worker_install_commands.py",
                "worker_install_fixtures.py",
            )
        },
        "environment": digest(environment_identity()),
    }


def build(project: Path, root: Path) -> None:
    stage = root / "project"
    shutil.copytree(
        project / "src",
        stage / "src",
        ignore=shutil.ignore_patterns("__pycache__", "*.pyc", "*.egg-info"),
    )
    for name in ("pyproject.toml", "README.md"):
        shutil.copy2(project / name, stage / name)
    wheels = root / "wheels"
    wheels.mkdir()
    checked_command(
        [
            sys.executable,
            "-B",
            "-m",
            "pip",
            "wheel",
            "--no-index",
            "--no-build-isolation",
            "--no-deps",
            "--wheel-dir",
            str(wheels),
            str(stage),
        ],
        cwd=stage,
    )
    (wheel,) = wheels.glob("lab_generate_skill-*.whl")
    checked_command(
        [
            sys.executable,
            "-B",
            "-m",
            "pip",
            "install",
            "--no-index",
            "--no-deps",
            "--no-compile",
            "--target",
            str(root / "site-packages"),
            str(wheel),
        ],
        cwd=root,
    )
    sources = {
        p: h
        for p, h in tree_files(project / "src/lab_generate_skill").items()
        if p.endswith(".py")
    }
    installed = {
        p: h
        for p, h in tree_files(root / "site-packages/lab_generate_skill").items()
        if p.endswith(".py")
    }
    if sources != installed:
        raise ValueError("Installed package differs from source")
    shutil.rmtree(stage)


def prepared_install(project: Path, cache: Path) -> tuple[Path, bool, str]:
    original = inputs(project)
    key = digest(original)
    target = cache / key
    with cache_lock(cache / f"{key}.lock"):
        if target.exists():
            receipt: Any = json.loads((target / "receipt.json").read_text())
            actual = tree_files(target)
            actual.pop("receipt.json", None)
            if receipt["key"] != key or receipt["files"] != actual:
                raise ValueError(
                    "Installation cache changed; retain evidence and use a new cache root"
                )
            return target, True, key
        cache.mkdir(parents=True, exist_ok=True)
        temporary = Path(tempfile.mkdtemp(prefix=".building-", dir=cache))
        try:
            build(project, temporary)
            if inputs(project) != original:
                raise ValueError(
                    "Source/environment changed during installation preparation"
                )
            (temporary / "receipt.json").write_text(
                json.dumps({"key": key, "files": tree_files(temporary)}, indent=2)
                + "\n"
            )
            for path in temporary.rglob("*"):
                path.chmod(0o555 if path.is_dir() else 0o444)
            temporary.chmod(0o555)
            temporary.rename(target)
        except BaseException:
            # Incomplete preparation is not accepted or overwritten on retry.
            # Keep it for diagnosis; its unique .building name is never read.
            raise
        return target, False, key
